window.FTA_TOUR = {"slug":"bach-splatinum","title":"Prelude in C","artist":"Splatinum","bpm":150,"key":"C major","seconds":61.6,"group":"bach","how":"Bach's Prelude in C (BWV 846), every note in his own rhythm, on golden-ratio FM bells. Around it, Splatinum's bass music: a roll into a vacuum, a talking wobble drop, and a riddim built on the piece's own long G pedal.","trick":"Bach did half the work. Bars 24-31 hold G in the bass for eight bars, the oldest build-up in the book, so that is where the riddim goes.","stops":[{"t":0,"label":"Bach on golden bells","text":"The Prelude as written, an arpeggio over one chord a bar, played on bells whose overtones sit at the golden ratio."},{"t":12.8,"label":"The roll","text":"The build: a snare roll speeding from quarters to 32nds while Bach keeps going."},{"t":25.6,"label":"Drop A","text":"Drop A: the womp takes Bach's lowest note of each bar as its root and talks in changing rates, 1, 1/2, 1/3 and 1/4 of a beat."},{"t":38.4,"label":"Drop B: the G pedal as riddim","text":"Drop B: Bach's G pedal as riddim, with triplet womps hammering G and the growl pushed harder."},{"t":51.2,"label":"Bach's cadence","text":"Bach's own cadence, bars 32-35, on bells over one last diving sub."}],"checks":{"lufs":-14.0,"tp":-1.6,"clicks":0,"sha":"CF6DB6FA2F1790EE"},"gram":{"rows":72,"cols":616,"lo":"C1","fps":10,"b64":""},"videos":[{"t":0,"clip":"video/circles.mp4","label":"What does one circle secretly run?","page":"/circles.html"},{"t":12.8,"clip":"video/blowup.mp4","label":"Blowup","page":"/blowup.html"},{"t":25.6,"clip":"video/remix-parrondo.mp4","label":"Parrondo's paradox","page":"/remix-parrondo.html"},{"t":38.4,"clip":"video/soundscape.mp4","label":"What does a drop look like?","page":null},{"t":51.2,"clip":"video/circles.mp4","label":"What does one circle secretly run?","page":"/circles.html"}]};
